import{p as t,b as o,C as a}from"./vue-vendor-de6b2611.js";const i={class:"markdown-body"},r=a('<h1>Firewall</h1><blockquote><p>iKOOLCORE R1, R2, and R2 Max support x86-based router systems such as pfSense, OPNsense, Panabit, OpenWRT, iKuai, and more.</p></blockquote><h2>How to Physically Install a Router System</h2><blockquote><p>This guide applies to all multi-port x86 devices. When installing OpenWRT or iKuai, use firmware with an <code>.img</code> file extension.</p></blockquote><h3>Preparation</h3><ul><li>Firmware: download it from the <a href="https://dl.ikoolcore.com">iKOOLCORE Download Center</a>.</li><li>Hard drive adapter: a USB-to-storage enclosure is the most convenient option. An RTL9210B-based adapter is recommended because it supports both SATA and NVMe drives.</li><li>Disk imaging software: <ul><li>macOS: <a href="https://www.balena.io/etcher">BalenaEtcher</a></li><li>Windows: <a href="https://www.balena.io/etcher">BalenaEtcher</a> or <a href="https://rufus.ie/en/">Rufus</a></li></ul></li></ul><blockquote><p>These tools can write the firmware image to a bootable drive.</p></blockquote><h3>Write the Firmware</h3><ol><li><p>Open the disk imaging software. The following example uses BalenaEtcher on macOS. Insert the drive enclosure containing the target drive into your PC or Mac.</p><p><img src="https://s2.loli.net/2023/03/18/6yqnoLZBXGewJdm.png" alt="Select the target drive"></p></li><li><p>Select the firmware image and the inserted drive, then click <strong>Write</strong>.</p><p><img src="https://s2.loli.net/2023/03/18/nBIcqLZhgmFDe6o.png" alt="Select the firmware"></p><p><img src="https://s2.loli.net/2023/03/18/9rRn7xF1zOZupYi.png" alt="Write the firmware"></p></li><li><p>After the write completes successfully, safely eject the drive.</p></li></ol><p>Install the prepared drive into the iKOOLCORE device, connect power and a monitor, and boot into the installed system. Use the system’s management address and management port to open its administration page.</p><h2>FAQ</h2><h3>How do I configure networking?</h3><blockquote><p>The configuration depends on your network layout and the router system you installed.</p></blockquote><h3>How do I expand the Overlay partition for OpenWRT?</h3><blockquote><p>Most available guides describe expanding partitions on SATA drives. For NVMe or eMMC drives, most modern firmware includes a <strong>Disk Management</strong> feature. You can change the partition size and format from the web interface under <strong>System</strong> → <strong>Disk Management</strong>. If the partition cannot be changed to <code>f2fs</code>, use command-line tools to format it with the required file system.</p></blockquote>',15),n=[r],d={__name:"firewall",setup(s,{expose:e}){return e({frontmatter:{}}),(c,p)=>(t(),o("div",i,n))}};export{d as default};
